def _is_only_comments(stmt):
    return all(not ln.strip() or ln.strip().startswith("--") for ln in stmt.splitlines())


def load_queries(path="balance.sql"):
    """Split balance.sql into individual SQL statements (comments kept)."""
    sql = Path(__file__).parent.joinpath(path).read_text()
    buf, queries = "", []
    for line in sql.splitlines(keepends=True):
        buf += line
        if sqlite3.complete_statement(buf):
            if not _is_only_comments(buf):
                queries.append(buf.strip())
            buf = ""
    if buf.strip() and not _is_only_comments(buf):
        queries.append(buf.strip())
    return queries

